using NAudio.Wave;

namespace Nagster.Sounds;

public enum SoundSource { BuiltIn, Windows, File }

/// <summary>A selectable alarm sound: its saved reference, a display name and where it comes from.</summary>
public sealed record SoundChoice(string Reference, string Name, SoundSource Source);

/// <summary>
/// Catalogue of alarm sounds. A sound is saved as a short reference so the choice survives the app
/// moving folders: "builtin:chime" for sounds generated by <see cref="ToneSynth"/>,
/// "windows:Alarm01" for sounds installed with Windows (in %WINDIR%\Media, never copied or shipped),
/// or a plain file path for a sound the user browsed to. A blank reference means "use the default".
/// </summary>
public static class SoundLibrary
{
    private const string BuiltInPrefix = "builtin:";
    private const string WindowsPrefix = "windows:";

    public static IReadOnlyList<SoundChoice> BuiltIn { get; } =
    [
        new(BuiltInPrefix + "beep", "Beep beep", SoundSource.BuiltIn),
        new(BuiltInPrefix + "chime", "Chime", SoundSource.BuiltIn),
        new(BuiltInPrefix + "ding", "Ding", SoundSource.BuiltIn),
        new(BuiltInPrefix + "rise", "Gentle rise", SoundSource.BuiltIn),
        new(BuiltInPrefix + "siren", "Siren", SoundSource.BuiltIn),
        new(BuiltInPrefix + "pulse", "Urgent pulse", SoundSource.BuiltIn)
    ];

    // The alarm and ringtone sets the Windows Clock app uses; other files in Media are short UI sounds.
    private static readonly string[] WindowsSoundFiles =
        [.. Enumerable.Range(1, 10).Select(i => $"Alarm{i:00}"), .. Enumerable.Range(1, 10).Select(i => $"Ring{i:00}")];

    private static readonly Dictionary<string, byte[]> RenderedBuiltIns = [];

    /// <summary>The Windows alarm and ring sounds that are present on this PC.</summary>
    public static IReadOnlyList<SoundChoice> WindowsSounds() =>
        WindowsSoundFiles.Where(name => File.Exists(WindowsMediaPath(name)))
            .Select(name => new SoundChoice(WindowsPrefix + name, FriendlyWindowsName(name), SoundSource.Windows))
            .ToList();

    /// <summary>Describes a saved reference, or returns null when it is blank.</summary>
    public static SoundChoice? Describe(string? reference)
    {
        if (string.IsNullOrWhiteSpace(reference)) return null;
        if (reference.StartsWith(BuiltInPrefix, StringComparison.Ordinal))
            return BuiltIn.FirstOrDefault(c => c.Reference == reference) ?? new SoundChoice(reference, "Unknown built-in sound", SoundSource.BuiltIn);
        if (reference.StartsWith(WindowsPrefix, StringComparison.Ordinal))
            return new SoundChoice(reference, FriendlyWindowsName(reference[WindowsPrefix.Length..]), SoundSource.Windows);
        return new SoundChoice(reference, Path.GetFileNameWithoutExtension(reference), SoundSource.File);
    }

    /// <summary>True when the reference points to a sound that can be played right now.</summary>
    public static bool IsAvailable(string? reference)
    {
        if (string.IsNullOrWhiteSpace(reference)) return false;
        if (reference.StartsWith(BuiltInPrefix, StringComparison.Ordinal)) return BuiltIn.Any(c => c.Reference == reference);
        if (reference.StartsWith(WindowsPrefix, StringComparison.Ordinal))
        {
            var name = reference[WindowsPrefix.Length..];
            return WindowsSoundFiles.Contains(name) && File.Exists(WindowsMediaPath(name));
        }
        return File.Exists(reference);
    }

    /// <summary>Opens an available sound for playback; the caller disposes the stream.</summary>
    /// <returns>The audio stream, or null when the reference is not available.</returns>
    public static WaveStream? Open(string reference)
    {
        if (!IsAvailable(reference)) return null;
        if (reference.StartsWith(BuiltInPrefix, StringComparison.Ordinal))
        {
            var pcm = RenderBuiltIn(reference[BuiltInPrefix.Length..]);
            return new RawSourceWaveStream(pcm, 0, pcm.Length, new WaveFormat(ToneSynth.SampleRate, 16, 1));
        }
        var path = reference.StartsWith(WindowsPrefix, StringComparison.Ordinal)
            ? WindowsMediaPath(reference[WindowsPrefix.Length..])
            : reference;
        return new MediaFoundationReader(path);
    }

    private static byte[] RenderBuiltIn(string id)
    {
        lock (RenderedBuiltIns)
        {
            if (!RenderedBuiltIns.TryGetValue(id, out var pcm))
                RenderedBuiltIns[id] = pcm = ToneSynth.Render(id) ?? throw new ArgumentException($"Unknown built-in sound '{id}'.", nameof(id));
            return pcm;
        }
    }

    private static string WindowsMediaPath(string name) =>
        Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "Media", name + ".wav");

    /// <summary>"Alarm01" becomes "Alarm 1".</summary>
    private static string FriendlyWindowsName(string name)
    {
        var digits = name.IndexOfAny("0123456789".ToCharArray());
        return digits >= 0 && int.TryParse(name[digits..], out var number) ? $"{name[..digits]} {number}" : name;
    }
}
